mapper.select:
/* SQL ID : UserMgrDAO.listUserMgr 설 명 : 사용자 목록 조회 */
SELECT ROW_NUMBER() OVER (ORDER BY A.REG_DTTM DESC, A.USER_ID) AS LINE_NO , COUNT(*) OVER () AS TOTAL_CNT , A.USER_ID , UAO.ORG_ID , ORG.ORGNM , A.USERNM , A.STDNT_NO , A.USER_TYCD , A.AC_RCD_TYCD , ADM_AUTH.AUTHRTNM AS ADMIN_AUTHRTNM , USERTY_AUTH.AUTHRTNM AS USER_TY_AUTHRTNM , CASE WHEN GUEST_AUTH.USER_ID IS NULL THEN 'N' ELSE 'Y' END AS GUEST_YN , A.REG_DTTM
ORDER BY A.REG_DTTM DESC, A.USER_ID

/*
    SQL ID : UserMgrDAO.countUserMgrStdntNo
    설  명 : 학번/사번 중복 건수 조회 (수정 시 본인 제외)
*/
SELECT COUNT(1)
FROM TB_LMS_USER
WHERE STDNT_NO = #{stdntNo}

    AND USER_ID != #{userId}

mapper.update:
/*
    SQL ID : UserMgrDAO.updateUserMgr
    설  명 : 사용자 수정
*/
UPDATE TB_LMS_USER
   SET USERNM = #{usernm}
     , USER_TYCD = #{userTycd}
     , STDNT_NO = #{stdntNo}
     , AC_RCD_TYCD = #{acRcdTycd}
     , DSBL_TYCD = #{dsblTycd}
     , DSBL_GRDCD = #{dsblGrdcd}
     , SNRYN = NVL(#{snryn}, 'N')
     , DSBLYN = NVL(#{dsblyn}, 'N')
     , PHOTO_FILE_ID = #{photoFileId}

     , USER_ID_ENCPSWD = #{userIdEncpswd}

     , MDFR_ID = #{mdfrId}
     , MOD_DTTM = FN_DTTM()
 WHERE USER_ID = #{userId}

/*
    SQL ID : UserMgrDAO.withdrawUserMgr
    설  명 : 사용자 탈퇴 처리 (손님 대상, 상태코드 WITHDRAW + 탈퇴일시 기록)
*/
UPDATE TB_LMS_USER
   SET USER_STSCD = 'WITHDRAW'
     , USER_ID_LEAVE_DTTM = FN_DTTM()
     , MDFR_ID = #{mdfrId}
     , MOD_DTTM = FN_DTTM()
 WHERE USER_ID = #{userId}

mapper.insert:
/*
    SQL ID : UserMgrDAO.mergeUserMgrCntct
    설  명 : 사용자 연락처 저장
             - CNTCT_TYCD : 휴대폰='MBL_PHN', 개인이메일='INDV_EML'
*/
MERGE INTO TB_LMS_USER_CNTCT T
USING (
    SELECT
          #{userId} AS USER_ID
        , #{cntctTycd} AS CNTCT_TYCD
    FROM DUAL
) S
   ON (
        T.USER_ID = S.USER_ID
    AND T.CNTCT_TYCD = S.CNTCT_TYCD
   )
WHEN MATCHED THEN
    UPDATE
       SET CNTCT = #{cntct}
         , MDFR_ID = #{mdfrId}
         , MOD_DTTM = FN_DTTM()
WHEN NOT MATCHED THEN
    INSERT (
          USER_CNTCT_ID
        , USER_ID
        , CNTCT_TYCD
        , CNTCT
        , RGTR_ID
        , REG_DTTM
    )
    VALUES (
          #{userCntctId}
        , #{userId}
        , #{cntctTycd}
        , #{cntct}
        , #{rgtrId}
        , FN_DTTM()
    )

mapper.delete:
/*
    SQL ID : UserMgrDAO.deleteUserMgrAuth
    설  명 : 사용자 관리자 그룹(ADM) 권한 삭제
*/
DELETE FROM TB_LMS_USER_AUTHRT
 WHERE USER_ID = #{userId}
   AND AUTHRT_ID IN (
       SELECT AUTHRT_ID FROM TB_LMS_AUTHRT WHERE AUTHRT_GRPCD = 'ADM'
   )

/*
    SQL ID : UserMgrDAO.deleteUserMgrAuthAll
    설  명 : 사용자 권한 전체 삭제
*/
DELETE FROM TB_LMS_USER_AUTHRT
 WHERE USER_ID = #{userId}

mapper.insert:
/*
    SQL ID : UserMgrDAO.insertUserMgrAuth
    설  명 : 사용자 권한 등록
*/
INSERT INTO TB_LMS_USER_AUTHRT (
      USER_AUTHRT_ID
    , USER_ID
    , AUTHRT_ID
    , ORG_ID
    , RGTR_ID
    , REG_DTTM
    , MDFR_ID
    , MOD_DTTM
) VALUES (
      #{userAuthrtId}
    , #{userId}
    , #{authrtId}
    , CASE WHEN #{authrtId} = 'AUTHRT_ID00099' THEN 'LMSBASIC' ELSE #{orgId} END
    , #{rgtrId}
    , FN_DTTM()
    , #{mdfrId}
    , FN_DTTM()
)

/*
    SQL ID : UserMgrDAO.insertUserInfoChgHstry
    설  명 : 사용자정보변경이력 등록
*/
