) VALUES (
      #{userInfoChgHstryId}
    , #{userId}
    , #{userinfoChgTycd}
    , #{chgbfrCts}
    , #{chgaftCts}
    , #{cntnIp}
    , #{cntnBrwsr}
    , #{cntnDvcTycd}
    , #{rgtrId}
    , FN_DTTM()
    , FN_DTTM()
)

/*
    SQL ID : UserMgrDAO.insertUserTelnoChgHstry
    설  명 : 사용자전화번호변경이력 등록
*/
